import AsyncStorage from '@react-native-async-storage/async-storage';
import { Feather, Ionicons } from '@expo/vector-icons';
import * as Haptics from 'expo-haptics';
import * as ImagePicker from 'expo-image-picker';
import { useEffect, useMemo, useState } from 'react';
import {
  Alert, Image, Linking, Modal, Platform, Pressable, ScrollView, StyleSheet,
  Text, TextInput, View,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useColors } from '@/hooks/useColors';

type Role = 'patient' | 'caretaker' | 'doctor';
type Section = 'home' | 'medicines' | 'inventory' | 'people' | 'history' | 'profile';
type Medicine = { id: string; name: string; strength: string; dose: number; times: string[]; frequency: string; start: string; end: string; photo: string; state: 'active' | 'paused' | 'ended'; changedBy: string; };
type Event = { id: string; medicineId: string; medicine: string; scheduledAt: string; respondedAt?: string; status: 'taken' | 'missed' | 'waiting'; patient: string; actor: string; sync: 'Synced' | 'Waiting to sync'; };
type Notice = { id: string; kind: 'sos' | 'missed' | 'voice' | 'update' | 'request'; title: string; body: string; time: string; read: boolean; };
type ConnectionRequest = { id: string; code: string; requester: string; requesterRole: Role; relationship: string; permission: string; status: 'pending' | 'accepted' | 'rejected'; };
type Connection = { id: string; name: string; code: string; role: Role; relationship: string; permission: string; initials: string; };
type InventoryItem = { medicineId: string; name: string; count: number; threshold: number; unit: string; };
type AppState = { authenticated: boolean; role: Role; section: Section; theme: 'light' | 'dark'; activePatient: string; userCode: string; displayName: string; email: string; password: string; age: string; sosNumber: string; medicines: Medicine[]; inventory: InventoryItem[]; events: Event[]; notices: Notice[]; requests: ConnectionRequest[]; connections: Connection[]; };

const logo = require('../../assets/images/mediguard-logo.jpg');
const referenceMedicine = require('../../assets/images/reference-login.jpg');
const seed: AppState = {
  authenticated: false, role: 'patient', section: 'home', theme: 'light', activePatient: 'Rajesh Kumar',
  userCode: 'MG-P-2048', displayName: 'Rajesh Kumar', email: 'rajesh@example.com', password: '', age: '72', sosNumber: '',
  medicines: [
    { id: 'med-amlodipine', name: 'Amlodipine', strength: '5 mg', dose: 1, times: ['08:00', '20:00'], frequency: 'Daily', start: '2026-08-01', end: '2026-10-31', photo: 'reference', state: 'active', changedBy: 'Meena Sharma' },
    { id: 'med-metformin', name: 'Metformin', strength: '500 mg', dose: 1, times: ['13:00'], frequency: 'Daily', start: '2026-08-01', end: '2026-10-31', photo: 'reference', state: 'active', changedBy: 'Meena Sharma' },
  ],
  events: [
    { id: 'evt-1', medicineId: 'med-amlodipine', medicine: 'Amlodipine', scheduledAt: '2026-08-23T08:00:00+05:30', respondedAt: '2026-08-23T08:03:00+05:30', status: 'taken', patient: 'Rajesh Kumar', actor: 'Rajesh Kumar', sync: 'Synced' },
    { id: 'evt-2', medicineId: 'med-metformin', medicine: 'Metformin', scheduledAt: '2026-08-23T13:00:00+05:30', status: 'waiting', patient: 'Rajesh Kumar', actor: '—', sync: 'Synced' },
  ],
  notices: [
    { id: 'n-1', kind: 'update', title: 'Schedule updated', body: 'Meena changed Amlodipine to 8:00 AM and 8:00 PM.', time: 'Today, 9:16 AM', read: false },
    { id: 'n-2', kind: 'voice', title: 'Voice message from Meena', body: '“Good morning Papa, please take this with water.”', time: 'Yesterday', read: false },
    { id: 'n-3', kind: 'missed', title: 'Medicine still waiting', body: 'Metformin is due at 1:00 PM for Rajesh.', time: 'Yesterday', read: true },
  ],
  inventory: [
    { medicineId: 'med-amlodipine', name: 'Amlodipine', count: 18, threshold: 7, unit: 'tablets' },
    { medicineId: 'med-metformin', name: 'Metformin', count: 32, threshold: 10, unit: 'tablets' },
  ],
  requests: [],
  connections: [],
};
const id = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
const prettyTime = (time: string) => { const [h, m] = time.split(':').map(Number); return `${h % 12 || 12}:${String(m).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`; };
const dateLabel = () => new Date().toLocaleDateString('en-IN', { weekday: 'long', month: 'long', day: 'numeric' });

export default function TabOneScreen() {
  const colors = useColors();
  const insets = useSafeAreaInsets();
  const [data, setData] = useState<AppState>(seed);
  const [loaded, setLoaded] = useState(false);
  const [showAlarm, setShowAlarm] = useState(false);
  const [showAdd, setShowAdd] = useState(false);
  const [showVoice, setShowVoice] = useState(false);
  const [showSos, setShowSos] = useState(false);
  const [showConnect, setShowConnect] = useState(false);
  const [showNotices, setShowNotices] = useState(false);
  const [showQr, setShowQr] = useState(false);
  const [qrMode, setQrMode] = useState<'show' | 'scan'>('show');
  const [recording, setRecording] = useState(false);
  const [draftName, setDraftName] = useState('');
  const [draftTime, setDraftTime] = useState('18:00');
  const [draftDose, setDraftDose] = useState(1);
  const [offline, setOffline] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signin');
  const [authRole, setAuthRole] = useState<Role>('patient');
  const [authName, setAuthName] = useState('');
  const [authAge, setAuthAge] = useState('');
  const [authEmail, setAuthEmail] = useState('');
  const [authPassword, setAuthPassword] = useState('');
  const [authDetails, setAuthDetails] = useState('');
  const [authConfirm, setAuthConfirm] = useState('');
  const [doctorStep, setDoctorStep] = useState(1);
  const [doctorEducation, setDoctorEducation] = useState('');
  const [doctorExperience, setDoctorExperience] = useState('');
  const [doctorLicense, setDoctorLicense] = useState('');
  const [doctorSpecialization, setDoctorSpecialization] = useState('');
  const [connectCode, setConnectCode] = useState('');
  const [sosDraft, setSosDraft] = useState('');

  useEffect(() => { AsyncStorage.getItem('mediguard-state').then((raw) => { if (raw) setData({ ...seed, ...(raw ? JSON.parse(raw) : {}) }); setLoaded(true); }); }, []);
  useEffect(() => { if (loaded) AsyncStorage.setItem('mediguard-state', JSON.stringify(data)); }, [data, loaded]);
  const patientMedicines = data.medicines.filter((m) => m.state !== 'ended');
  const nextDose = useMemo(() => patientMedicines.flatMap((m) => m.times.map((time) => ({ ...m, time }))).sort((a, b) => a.time.localeCompare(b.time))[0], [patientMedicines]);
  const completed = data.events.filter((e) => e.status === 'taken').length;
  const adherence = Math.round((completed / Math.max(data.events.length, 1)) * 100);
  const changeSection = (section: Section) => { Haptics.selectionAsync(); setData((d) => ({ ...d, section })); };
  const switchRole = (role: Role) => { Haptics.selectionAsync(); setData((d) => ({ ...d, role, section: 'home' })); };
  const tickDose = (medicine: Medicine) => {
    const event: Event = { id: id('evt'), medicineId: medicine.id, medicine: medicine.name, scheduledAt: new Date().toISOString(), respondedAt: new Date().toISOString(), status: 'taken', patient: data.activePatient, actor: data.role === 'patient' ? data.activePatient : 'Meena Sharma', sync: offline ? 'Waiting to sync' : 'Synced' };
    setData((d) => {
      const patientResponded = data.role === 'patient';
      const nextInventory = patientResponded ? d.inventory.map((item) => item.medicineId === medicine.id ? { ...item, count: Math.max(0, item.count - medicine.dose) } : item) : d.inventory;
      const low = patientResponded ? nextInventory.find((item) => item.medicineId === medicine.id && item.count <= item.threshold) : undefined;
      return { ...d, inventory: nextInventory, events: [event, ...d.events], notices: [{ id: id('notice'), kind: low ? 'missed' : 'update', title: low ? `${medicine.name} is running low` : 'Dose recorded', body: low ? `Only ${low.count} ${low.unit} remain for Rajesh. Please arrange the next refill.` : `${medicine.name} marked taken by ${event.actor}.`, time: 'Just now', read: false }, ...d.notices] };
    });
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success); setShowAlarm(false);
  };
  const snooze = () => { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium); setShowAlarm(false); Alert.alert('Alarm snoozed', 'We will remind you again in 5 minutes.'); };
  const choosePhoto = async () => { const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.75 }); if (!result.canceled) Alert.alert('Photo ready', 'Medicine photo attached to this schedule.'); };
  const saveMedicine = () => {
    if (!draftName.trim()) { Alert.alert('Medicine name needed', 'Add the name so the Patient can recognize it.'); return; }
    const medicine: Medicine = { id: id('med'), name: draftName.trim(), strength: '10 mg', dose: draftDose, times: [draftTime], frequency: 'Daily', start: '2026-08-23', end: '2026-10-31', photo: 'reference', state: 'active', changedBy: 'Meena Sharma' };
    setData((d) => ({ ...d, medicines: [medicine, ...d.medicines], notices: [{ id: id('notice'), kind: 'update', title: 'New medicine schedule', body: `Meena added ${medicine.name} for Rajesh Kumar.`, time: 'Just now', read: false }, ...d.notices] }));
    setDraftName(''); setShowAdd(false); Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
  };
  const togglePause = (medicine: Medicine) => setData((d) => ({ ...d, medicines: d.medicines.map((m) => m.id === medicine.id ? { ...m, state: m.state === 'paused' ? 'active' : 'paused', changedBy: 'Meena Sharma' } : m), notices: [{ id: id('notice'), kind: 'update', title: `Schedule ${medicine.state === 'paused' ? 'resumed' : 'paused'}`, body: `Meena ${medicine.state === 'paused' ? 'resumed' : 'paused'} ${medicine.name} for Rajesh Kumar.`, time: 'Just now', read: false }, ...d.notices] }));
  const deleteMedicine = (medicine: Medicine) => Alert.alert('Delete this schedule?', `${medicine.name} will stop generating new doses. Historical responses will stay safe.`, [{ text: 'Keep schedule', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: () => setData((d) => ({ ...d, medicines: d.medicines.map((m) => m.id === medicine.id ? { ...m, state: 'ended' } : m), notices: [{ id: id('notice'), kind: 'update', title: 'Schedule ended', body: `${medicine.name} was ended by ${d.displayName}. Historical records were preserved.`, time: 'Just now', read: false }, ...d.notices] })) }]);
  const removeRelationship = () => Alert.alert('Remove Daughter connection?', 'Historical records will stay safe, but access ends immediately.', [{ text: 'Keep', style: 'cancel' }, { text: 'Remove', style: 'destructive', onPress: () => Alert.alert('Connection removed', 'Daughter can no longer view Rajesh’s care.') }]);
  const signUp = () => {
    if (!authName.trim() || !authEmail.trim() || !authPassword.trim() || !authConfirm.trim()) { Alert.alert('A few details are missing', 'Please add your name, Gmail, password and confirm password.'); return; }
    if (authPassword !== authConfirm) { Alert.alert('Passwords do not match', 'Please make sure password and confirm password are the same.'); return; }
    if (authRole === 'doctor' && doctorStep === 1) { setDoctorStep(2); return; }
    if (authRole === 'doctor' && (!doctorEducation.trim() || !doctorExperience.trim() || !doctorLicense.trim() || !doctorSpecialization.trim())) { Alert.alert('Doctor details needed', 'Please complete education, experience, medicine licence and core specialisation.'); return; }
    const prefix = authRole === 'patient' ? 'P' : authRole === 'caretaker' ? 'C' : 'D';
    const userCode = `MG-${prefix}-${String(Date.now()).slice(-4)}`;
    setData((d) => ({ ...d, authenticated: true, role: authRole, displayName: authName.trim(), activePatient: authRole === 'patient' ? authName.trim() : d.activePatient, userCode, email: authEmail.trim(), password: authPassword, age: authAge, section: 'home', notices: [{ id: id('notice'), kind: 'update', title: 'Welcome to MediGuard', body: `Your private usercode is ${userCode}.`, time: 'Just now', read: false }, ...d.notices] }));
    setAuthPassword('');
    setAuthConfirm('');
    setDoctorStep(1);
  };
  const signIn = () => {
    const matchesId = authEmail.trim().toLowerCase() === data.email.toLowerCase() || authEmail.trim().toUpperCase() === data.userCode.toUpperCase();
    if (!matchesId || authPassword !== data.password) { Alert.alert('Could not sign in', 'Check your usercode or Gmail and password, then try again.'); return; }
    setData((d) => ({ ...d, authenticated: true, section: 'home' })); setAuthPassword('');
  };
  const logout = () => setData((d) => ({ ...d, authenticated: false, section: 'home' }));
  const submitConnection = () => {
    if (!connectCode.trim()) { Alert.alert('Patient usercode needed', 'Enter the Patient usercode to send a connection request.'); return; }
    const request: ConnectionRequest = { id: id('request'), code: connectCode.trim().toUpperCase(), requester: data.displayName || 'Meena Sharma', requesterRole: data.role, relationship: 'Caretaker', permission: 'Manage medicines and receive alerts', status: 'pending' };
    setData((d) => ({ ...d, requests: [request, ...d.requests], notices: [{ id: id('notice'), kind: 'request', title: 'Connection request sent', body: `Waiting for the Patient with ID ${request.code} to confirm.`, time: 'Just now', read: false }, ...d.notices] }));
    setConnectCode(''); setShowConnect(false); Alert.alert('Request sent', `The Patient must confirm this request in their MediGuard account.`);
  };
  const respondToRequest = (request: ConnectionRequest, accepted: boolean) => {
    setData((d) => ({ ...d, requests: d.requests.map((r) => r.id === request.id ? { ...r, status: accepted ? 'accepted' : 'rejected' } : r), connections: accepted ? [{ id: request.id, name: request.requester, code: request.code, role: request.requesterRole, relationship: request.relationship, permission: request.permission, initials: request.requester.slice(0, 2).toUpperCase() }, ...d.connections] : d.connections, notices: [{ id: id('notice'), kind: 'request', title: accepted ? 'Connection confirmed' : 'Request declined', body: `${request.requester} ${accepted ? 'is now connected to' : 'is not connected to'} ${d.displayName}.`, time: 'Just now', read: false }, ...d.notices] }));
  };
  const saveSos = () => { if (!sosDraft.trim()) { Alert.alert('Number needed', 'Add an emergency number so SOS can call the right person.'); return; } setData((d) => ({ ...d, sosNumber: sosDraft.trim() })); setSosDraft(''); setShowSos(false); };
  const triggerSos = () => {
    if (!data.sosNumber) { setSosDraft(''); setShowSos(true); return; }
    Alert.alert('Call emergency contact?', data.sosNumber, [{ text: 'Cancel', style: 'cancel' }, { text: 'Call now', onPress: () => Linking.openURL(`tel:${data.sosNumber.replace(/\s/g, '')}`) }]);
  };
  const nav: { key: Section; label: string; icon: keyof typeof Feather.glyphMap }[] = [{ key: 'home', label: 'Today', icon: 'sun' }, { key: 'medicines', label: 'Medicines', icon: 'grid' }, ...(data.role === 'caretaker' ? [{ key: 'inventory' as Section, label: 'Stock', icon: 'archive' as keyof typeof Feather.glyphMap }] : []), { key: 'people', label: 'People', icon: 'users' }, { key: 'history', label: 'History', icon: 'activity' }, { key: 'profile', label: 'Profile', icon: 'user' }];

  if (!loaded) return <View style={[styles.center, { backgroundColor: colors.background }]}><Ionicons name="heart-outline" size={32} color={colors.primary} /><Text style={[styles.caption, { color: colors.mutedForeground }]}>Loading your care plan…</Text></View>;
  if (!data.authenticated) return <AuthScreenV2 colors={colors} mode={authMode} role={authRole} name={authName} age={authAge} email={authEmail} password={authPassword} confirm={authConfirm} details={authDetails} doctorStep={doctorStep} doctorEducation={doctorEducation} doctorExperience={doctorExperience} doctorLicense={doctorLicense} doctorSpecialization={doctorSpecialization} setMode={setAuthMode} setRole={setAuthRole} setName={setAuthName} setAge={setAuthAge} setEmail={setAuthEmail} setPassword={setAuthPassword} setConfirm={setAuthConfirm} setDetails={setAuthDetails} setDoctorStep={setDoctorStep} setDoctorEducation={setDoctorEducation} setDoctorExperience={setDoctorExperience} setDoctorLicense={setDoctorLicense} setDoctorSpecialization={setDoctorSpecialization} onSignIn={signIn} onSignUp={signUp} />;
  return (
    <View style={[styles.screen, { backgroundColor: colors.background, paddingTop: insets.top }]}>
        <View style={styles.topbar}>
        <View style={styles.brand}><Image source={logo} style={styles.logo} /><View><Text style={[styles.brandName, { color: colors.foreground }]}>Medi<Text style={{ color: colors.primary }}>guard</Text></Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{data.role === 'patient' ? 'Your gentle daily care' : data.role === 'caretaker' ? 'Care circle' : 'Clinical view'}</Text></View></View>
        <View style={styles.topActions}>{data.role === 'caretaker' && <Pressable testID="activity-bell" onPress={() => setShowNotices(true)} style={styles.topIcon}><Feather name="bell" size={20} color={colors.primary} />{data.notices.some((n) => !n.read) && <View style={styles.notificationDot} />}</Pressable>}<Pressable testID="qr-button" onPress={() => { setQrMode('show'); setShowQr(true); }} style={styles.topIcon}><Feather name="maximize" size={20} color={colors.primary} /></Pressable><Pressable onPress={() => changeSection('profile')} style={styles.profileIcon}><View style={[styles.avatar, { backgroundColor: '#f4c3d3' }]}><Text style={styles.avatarText}>{data.role === 'doctor' ? 'DR' : data.role === 'caretaker' ? 'MS' : 'RK'}</Text></View><Text style={[styles.codeUnderIcon, { color: colors.primary }]}>{data.userCode}</Text></Pressable></View>
      </View>
      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={styles.content}>
        {data.role !== 'patient' && <View style={[styles.patientBanner, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={[styles.patientPhoto, { backgroundColor: '#f4c3d3' }]}><Text style={styles.patientInitials}>RK</Text></View><View style={{ flex: 1 }}><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>SELECTED PATIENT</Text><Text style={[styles.h2, { color: colors.foreground }]}>{data.activePatient}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>MG-2048 · Father</Text></View><Feather name="chevron-down" size={20} color={colors.mutedForeground} /></View>}
        {data.role === 'patient' && data.section === 'home' && <PatientHome colors={colors} medicines={patientMedicines} nextDose={nextDose} onAlarm={() => setShowAlarm(true)} onVoice={() => setShowVoice(true)} onSOS={triggerSos} />}
        {data.role === 'caretaker' && data.section === 'home' && <CaretakerHome colors={colors} medicines={patientMedicines} notices={data.notices} onAdd={() => setShowAdd(true)} onPause={togglePause} onDelete={deleteMedicine} onOpenAlarm={() => setShowAlarm(true)} />}
        {data.role === 'doctor' && data.section === 'home' && <DoctorHome colors={colors} adherence={adherence} events={data.events} medicines={patientMedicines} />}
        {data.section === 'medicines' && <MedicineSection colors={colors} role={data.role} medicines={patientMedicines} onAdd={() => setShowAdd(true)} onPause={togglePause} onDelete={deleteMedicine} onAlarm={() => setShowAlarm(true)} />}
        {data.section === 'inventory' && <InventorySection colors={colors} inventory={data.inventory} onAdjust={(medicineId: string, delta: number) => setData((d) => ({ ...d, inventory: d.inventory.map((item) => item.medicineId === medicineId ? { ...item, count: Math.max(0, item.count + delta) } : item) }))} />}
        {data.section === 'people' && <PeopleSection colors={colors} role={data.role} connections={data.connections} requests={data.requests} onConnect={() => setShowConnect(true)} onRespond={respondToRequest} onRemove={removeRelationship} />}
        {data.section === 'history' && <HistorySection colors={colors} events={data.events} />}
        {data.section === 'profile' && <ProfileSection colors={colors} role={data.role} userCode={data.userCode} connections={data.connections} sosNumber={data.sosNumber} onSOS={triggerSos} onLogout={logout} onPeople={() => changeSection('people')} />}
      </ScrollView>
      <View style={[styles.bottomNav, { backgroundColor: colors.card, borderTopColor: colors.border, paddingBottom: Platform.OS === 'web' ? 34 : Math.max(insets.bottom, 10) }]}>{nav.map((item) => <Pressable key={item.key} testID={`nav-${item.key}`} onPress={() => changeSection(item.key)} style={styles.navItem}><Feather name={item.icon} size={21} color={data.section === item.key ? colors.primary : colors.mutedForeground} /><Text style={[styles.navLabel, { color: data.section === item.key ? colors.primary : colors.mutedForeground }]}>{item.label}</Text>{item.key === 'profile' && data.notices.some((n) => !n.read) ? <View style={styles.badge} /> : null}</Pressable>)}</View>
      <Modal visible={showAlarm} animationType="fade"><Alarm colors={colors} medicine={nextDose || patientMedicines[0]} onTick={tickDose} onSnooze={snooze} onVoice={() => { setShowAlarm(false); setShowVoice(true); }} onClose={() => setShowAlarm(false)} /></Modal>
      <Modal visible={showAdd} animationType="slide" transparent><View style={styles.sheetBackdrop}><View style={[styles.sheet, { backgroundColor: colors.card }]}><View style={styles.sheetHandle} /><View style={styles.sheetHeader}><View><Text style={[styles.sheetTitle, { color: colors.foreground }]}>Add for Rajesh Kumar</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>MG-2048 · Connected as Primary Caretaker</Text></View><Pressable onPress={() => setShowAdd(false)}><Feather name="x" size={23} color={colors.mutedForeground} /></Pressable></View><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>MEDICINE PHOTO</Text><Pressable onPress={choosePhoto} style={[styles.photoPicker, { backgroundColor: colors.muted, borderColor: colors.border }]}><Image source={referenceMedicine} style={styles.pickerImage} /><View><Text style={[styles.rowTitle, { color: colors.foreground }]}>Use a clear photo</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Camera or photo library</Text></View><Feather name="camera" size={22} color={colors.primary} /></Pressable><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>MEDICINE NAME</Text><TextInput value={draftName} onChangeText={setDraftName} placeholder="e.g. Amlodipine" placeholderTextColor={colors.mutedForeground} style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.background }]} /><View style={styles.formRow}><View style={{ flex: 1 }}><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>DOSAGE</Text><View style={[styles.stepper, { borderColor: colors.border }]}><Pressable onPress={() => setDraftDose(Math.max(1, draftDose - 1))} style={styles.stepButton}><Feather name="minus" size={18} color={colors.primary} /></Pressable><Text style={[styles.doseValue, { color: colors.foreground }]}>{draftDose} tablet</Text><Pressable onPress={() => setDraftDose(draftDose + 1)} style={styles.stepButton}><Feather name="plus" size={18} color={colors.primary} /></Pressable></View></View><View style={{ flex: 1 }}><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>TIME</Text><TextInput value={draftTime} onChangeText={setDraftTime} keyboardType="numbers-and-punctuation" style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.background }]} /></View></View><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>PATIENT PREVIEW</Text><View style={[styles.preview, { backgroundColor: '#fff0f5' }]}><Feather name="clock" size={18} color={colors.primary} /><Text style={[styles.previewText, { color: colors.foreground }]}>{prettyTime(draftTime)} · {draftName || 'Your medicine'} · {draftDose} tablet</Text></View><Pressable testID="save-medicine" onPress={saveMedicine} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.primaryButtonText}>Save schedule</Text><Feather name="check" size={20} color={colors.primaryForeground} /></Pressable></View></View></Modal>
      <Modal visible={showVoice} animationType="slide" transparent><View style={styles.sheetBackdrop}><View style={[styles.voiceSheet, { backgroundColor: colors.card }]}><View style={styles.sheetHandle} /><Pressable onPress={() => { setShowVoice(false); setRecording(false); }} style={styles.closeCircle}><Feather name="x" size={20} color={colors.foreground} /></Pressable><Text style={[styles.sheetTitle, { color: colors.foreground }]}>Send a voice message</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Your Caretaker will receive the original recording.</Text><View style={[styles.recordCircle, { backgroundColor: recording ? '#f7d2df' : colors.secondary }]}><Pressable onPress={() => { setRecording(!recording); Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium); }} style={[styles.recordButton, { backgroundColor: colors.primary }]}><Feather name={recording ? 'square' : 'mic'} size={34} color="#fff" /></Pressable></View><Text style={[styles.recordStatus, { color: colors.foreground }]}>{recording ? 'Recording… 00:12' : 'Tap to record'}</Text>{!recording && <Pressable onPress={() => { setShowVoice(false); Alert.alert('Voice message saved', offline ? 'Waiting to sync' : 'Delivered to Meena'); }} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.primaryButtonText}>Send message</Text><Feather name="send" size={18} color="#fff" /></Pressable>}</View></View></Modal>
      <Modal visible={showConnect} animationType="slide" transparent><View style={styles.sheetBackdrop}><View style={[styles.sheet, { backgroundColor: colors.card }]}><View style={styles.sheetHandle} /><View style={styles.sheetHeader}><View><Text style={[styles.sheetTitle, { color: colors.foreground }]}>Connect a Patient</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>The Patient must confirm using their own ID.</Text></View><Pressable onPress={() => setShowConnect(false)}><Feather name="x" size={23} color={colors.mutedForeground} /></Pressable></View><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>PATIENT USERCODE</Text><TextInput autoCapitalize="characters" value={connectCode} onChangeText={setConnectCode} placeholder="e.g. MG-P-2048" placeholderTextColor={colors.mutedForeground} style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.background }]} /><View style={[styles.preview, { backgroundColor: colors.secondary }]}><Feather name="shield" size={18} color={colors.primary} /><Text style={[styles.previewText, { color: colors.foreground }]}>A request will appear in that Patient’s account for confirmation.</Text></View><Pressable testID="send-connection" onPress={submitConnection} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.primaryButtonText}>Send connection request</Text><Feather name="send" size={18} color="#fff" /></Pressable></View></View></Modal>
      <Modal visible={showSos} animationType="slide" transparent><View style={styles.sheetBackdrop}><View style={[styles.sheet, { backgroundColor: colors.card }]}><View style={styles.sheetHandle} /><View style={styles.sheetHeader}><View><Text style={[styles.sheetTitle, { color: colors.foreground }]}>Set SOS number</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>This number will be called when you touch SOS.</Text></View><Pressable onPress={() => setShowSos(false)}><Feather name="x" size={23} color={colors.mutedForeground} /></Pressable></View><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>EMERGENCY CONTACT</Text><TextInput value={sosDraft} onChangeText={setSosDraft} keyboardType="phone-pad" placeholder="+91 98765 43210" placeholderTextColor={colors.mutedForeground} style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.background }]} /><Pressable testID="save-sos" onPress={saveSos} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.primaryButtonText}>Save SOS number</Text><Feather name="check" size={18} color="#fff" /></Pressable></View></View></Modal>
      <Modal visible={showNotices} animationType="slide" transparent><View style={styles.sheetBackdrop}><View style={[styles.noticeSheet, { backgroundColor: colors.card }]}><View style={styles.sheetHandle} /><View style={styles.sheetHeader}><View><Text style={[styles.sheetTitle, { color: colors.foreground }]}>Activity notifications</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Recent activity for Rajesh Kumar</Text></View><Pressable onPress={() => setShowNotices(false)}><Feather name="x" size={23} color={colors.mutedForeground} /></Pressable></View>{data.notices.map((n) => <View key={n.id} style={styles.noticeRow}><View style={[styles.activityIcon, { backgroundColor: n.kind === 'missed' ? '#fff0d5' : colors.secondary }]}><Feather name={n.kind === 'missed' ? 'alert-triangle' : 'bell'} size={16} color={n.kind === 'missed' ? '#c98227' : colors.primary} /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{n.title}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{n.body}</Text><Text style={[styles.syncSmall, { color: colors.mutedForeground }]}>{n.time}</Text></View></View>)}</View></View></Modal>
      <Modal visible={showQr} animationType="slide" transparent><View style={styles.sheetBackdrop}><View style={[styles.sheet, { backgroundColor: colors.card }]}><View style={styles.sheetHandle} /><View style={styles.sheetHeader}><View><Text style={[styles.sheetTitle, { color: colors.foreground }]}>Connect with QR</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Use your unique code to connect safely.</Text></View><Pressable onPress={() => setShowQr(false)}><Feather name="x" size={23} color={colors.mutedForeground} /></Pressable></View><View style={styles.authSwitch}><Pressable onPress={() => setQrMode('show')} style={[styles.authSwitchItem, qrMode === 'show' ? { backgroundColor: colors.primary } : null]}><Text style={[styles.authSwitchText, { color: qrMode === 'show' ? '#fff' : colors.mutedForeground }]}>Show my QR</Text></Pressable><Pressable onPress={() => setQrMode('scan')} style={[styles.authSwitchItem, qrMode === 'scan' ? { backgroundColor: colors.primary } : null]}><Text style={[styles.authSwitchText, { color: qrMode === 'scan' ? '#fff' : colors.mutedForeground }]}>Scan QR</Text></Pressable></View>{qrMode === 'show' ? <View style={styles.qrCard}><View style={styles.qrFake}>{Array.from({ length: 49 }).map((_, i) => <View key={i} style={[styles.qrPixel, { backgroundColor: ((i * 17 + 3) % 7 < 3 || i % 11 === 0) ? '#35233a' : '#fff' }]} />)}</View><Text style={[styles.userCode, { color: colors.primary }]}>{data.userCode}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Let another MediGuard user scan this code.</Text></View> : <><View style={[styles.scanPlaceholder, { backgroundColor: colors.secondary }]}><Feather name="camera" size={31} color={colors.primary} /><Text style={[styles.rowTitle, { color: colors.foreground }]}>Camera scanner ready</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Enter the usercode from the QR if camera scanning is unavailable.</Text></View><TextInput autoCapitalize="characters" value={connectCode} onChangeText={setConnectCode} placeholder="MG-P-2048" placeholderTextColor={colors.mutedForeground} style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.background }]} /><Pressable onPress={() => { setShowQr(false); setShowConnect(true); }} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.primaryButtonText}>Use scanned code</Text><Feather name="arrow-right" size={18} color="#fff" /></Pressable></>}</View></View></Modal>
    </View>
  );
}

function AuthScreen({ colors, mode, role, name, age, email, password, details, setMode, setRole, setName, setAge, setEmail, setPassword, setDetails, onSignIn, onSignUp }: any) {
  const signup = mode === 'signup';
  return <ScrollView contentContainerStyle={[styles.authScreen, { backgroundColor: colors.background }]} keyboardShouldPersistTaps="handled"><Image source={logo} style={styles.authLogo} /><Text style={[styles.authBrand, { color: colors.foreground }]}>Medi<Text style={{ color: colors.primary }}>guard</Text></Text><Text style={[styles.authTagline, { color: colors.mutedForeground }]}>{signup ? 'Create a care account that keeps everyone connected.' : 'Safe, simple care for every day.'}</Text><View style={styles.authSwitch}><Pressable onPress={() => setMode('signin')} style={[styles.authSwitchItem, signup ? null : { backgroundColor: colors.primary }]}><Text style={[styles.authSwitchText, { color: signup ? colors.mutedForeground : '#fff' }]}>Sign in</Text></Pressable><Pressable onPress={() => setMode('signup')} style={[styles.authSwitchItem, signup ? { backgroundColor: colors.primary } : null]}><Text style={[styles.authSwitchText, { color: signup ? '#fff' : colors.mutedForeground }]}>Sign up</Text></Pressable></View>{signup && <><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>I AM A</Text><View style={styles.authRoleGrid}>{(['patient', 'caretaker', 'doctor'] as Role[]).map((r) => <Pressable key={r} onPress={() => setRole(r)} style={[styles.authRoleCard, { backgroundColor: role === r ? colors.secondary : colors.card, borderColor: role === r ? colors.primary : colors.border }]}><Feather name={r === 'patient' ? 'heart' : r === 'caretaker' ? 'users' : 'activity'} size={22} color={role === r ? colors.primary : colors.mutedForeground} /><Text style={[styles.authRoleText, { color: colors.foreground }]}>{r[0].toUpperCase() + r.slice(1)}</Text></Pressable>)}</View><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>YOUR DETAILS</Text><TextInput value={name} onChangeText={setName} placeholder={role === 'doctor' ? 'Full name and title' : 'Full name'} placeholderTextColor={colors.mutedForeground} style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} /><TextInput value={age} onChangeText={setAge} placeholder={role === 'doctor' ? 'Years of experience' : 'Age'} placeholderTextColor={colors.mutedForeground} keyboardType="number-pad" style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} />{role === 'doctor' && <TextInput value={details} onChangeText={setDetails} placeholder="Degrees, qualifications, license, hospital, specialization and certificates" placeholderTextColor={colors.mutedForeground} multiline style={[styles.input, styles.detailsInput, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} />}</>}<TextInput value={email} onChangeText={setEmail} placeholder={signup ? 'Gmail address' : 'Usercode or Gmail'} placeholderTextColor={colors.mutedForeground} autoCapitalize="none" keyboardType="email-address" style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} /><TextInput value={password} onChangeText={setPassword} placeholder="Password" placeholderTextColor={colors.mutedForeground} secureTextEntry style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} /><Pressable testID={signup ? 'create-account' : 'sign-in'} onPress={signup ? onSignUp : onSignIn} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.primaryButtonText}>{signup ? 'Create account' : 'Sign in'}</Text><Feather name="arrow-right" size={19} color="#fff" /></Pressable>{signup && <Text style={[styles.authNote, { color: colors.mutedForeground }]}>After account creation, MediGuard gives you a unique usercode for safe connections.</Text>}</ScrollView>;
}

function AuthScreenV2({ colors, mode, role, name, age, email, password, confirm, doctorStep, doctorEducation, doctorExperience, doctorLicense, doctorSpecialization, setMode, setRole, setName, setAge, setEmail, setPassword, setConfirm, setDoctorStep, setDoctorEducation, setDoctorExperience, setDoctorLicense, setDoctorSpecialization, onSignIn, onSignUp }: any) {
  const signup = mode === 'signup';
  const doctorDetails = signup && role === 'doctor' && doctorStep === 2;
  return <ScrollView contentContainerStyle={[styles.authScreen, { backgroundColor: colors.background }]} keyboardShouldPersistTaps="handled">
    <Image source={logo} style={styles.authLogo} />
    <Text style={[styles.authBrand, { color: colors.foreground }]}>Medi<Text style={{ color: colors.primary }}>guard</Text></Text>
    <Text style={[styles.authTagline, { color: colors.mutedForeground }]}>{signup ? (doctorDetails ? 'Complete your professional profile.' : 'Create a care account that keeps everyone connected.') : 'Safe, simple care for every day.'}</Text>
    <View style={styles.authSwitch}><Pressable onPress={() => { setMode('signin'); setDoctorStep(1); }} style={[styles.authSwitchItem, signup ? null : { backgroundColor: colors.primary }]}><Text style={[styles.authSwitchText, { color: signup ? colors.mutedForeground : '#fff' }]}>Sign in</Text></Pressable><Pressable onPress={() => setMode('signup')} style={[styles.authSwitchItem, signup ? { backgroundColor: colors.primary } : null]}><Text style={[styles.authSwitchText, { color: signup ? '#fff' : colors.mutedForeground }]}>Sign up</Text></Pressable></View>
    {signup && !doctorDetails && <><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>I AM A</Text><View style={styles.authRoleGrid}>{(['patient', 'caretaker', 'doctor'] as Role[]).map((r) => <Pressable key={r} onPress={() => { setRole(r); setDoctorStep(1); }} style={[styles.authRoleCard, { backgroundColor: role === r ? colors.secondary : colors.card, borderColor: role === r ? colors.primary : colors.border }]}><Feather name={r === 'patient' ? 'heart' : r === 'caretaker' ? 'users' : 'activity'} size={22} color={role === r ? colors.primary : colors.mutedForeground} /><Text style={[styles.authRoleText, { color: colors.foreground }]}>{r[0].toUpperCase() + r.slice(1)}</Text></Pressable>)}</View><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>{role === 'doctor' ? 'DOCTOR ACCOUNT' : 'YOUR DETAILS'}</Text><TextInput value={name} onChangeText={setName} placeholder={role === 'doctor' ? 'Doctor name' : 'Full name'} placeholderTextColor={colors.mutedForeground} style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} />{role !== 'doctor' && <TextInput value={age} onChangeText={setAge} placeholder="Age" placeholderTextColor={colors.mutedForeground} keyboardType="number-pad" style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} />}</>}
    {doctorDetails && <><Pressable onPress={() => setDoctorStep(1)} style={styles.backStep}><Feather name="arrow-left" size={17} color={colors.primary} /><Text style={[styles.link, { color: colors.primary }]}>Back to doctor account</Text></Pressable><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>PROFESSIONAL DETAILS</Text><TextInput value={doctorEducation} onChangeText={setDoctorEducation} placeholder="Education qualification" placeholderTextColor={colors.mutedForeground} style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} /><TextInput value={doctorExperience} onChangeText={setDoctorExperience} placeholder="Years of experience" placeholderTextColor={colors.mutedForeground} keyboardType="number-pad" style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} /><TextInput value={doctorLicense} onChangeText={setDoctorLicense} placeholder="Medicine licence number" placeholderTextColor={colors.mutedForeground} style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} /><TextInput value={doctorSpecialization} onChangeText={setDoctorSpecialization} placeholder="Core specialisation" placeholderTextColor={colors.mutedForeground} style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} /></>}
    {!doctorDetails && <><TextInput value={email} onChangeText={setEmail} placeholder={signup ? 'Gmail address' : 'Usercode or Gmail'} placeholderTextColor={colors.mutedForeground} autoCapitalize="none" keyboardType="email-address" style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} /><TextInput value={password} onChangeText={setPassword} placeholder="Password" placeholderTextColor={colors.mutedForeground} secureTextEntry style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} />{signup && <TextInput value={confirm} onChangeText={setConfirm} placeholder="Confirm password" placeholderTextColor={colors.mutedForeground} secureTextEntry style={[styles.input, { borderColor: colors.border, color: colors.foreground, backgroundColor: colors.card }]} />}</>}
    <Pressable testID={signup ? 'create-account' : 'sign-in'} onPress={signup ? onSignUp : onSignIn} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.primaryButtonText}>{signup ? (doctorDetails ? 'Create doctor account' : role === 'doctor' ? 'Continue' : 'Create account') : 'Sign in'}</Text><Feather name="arrow-right" size={19} color="#fff" /></Pressable>
    {signup && <Text style={[styles.authNote, { color: colors.mutedForeground }]}>Your unique usercode will appear below your profile icon after account creation.</Text>}
  </ScrollView>;
}

function PatientHome({ colors, medicines, nextDose, onAlarm, onVoice, onSOS }: any) {
  return <><View style={styles.greeting}><Text style={[styles.eyebrow, { color: colors.primary }]}>SUNDAY · AUGUST 23</Text><Text style={[styles.h1, { color: colors.foreground }]}>Good morning, Rajesh</Text><Text style={[styles.subhead, { color: colors.mutedForeground }]}>You are cared for, every day.</Text></View><Pressable testID="patient-sos" onPress={onSOS} style={styles.frontSos}><View style={styles.sosPulse}><Feather name="phone-call" size={25} color="#fff" /></View><View style={{ flex: 1 }}><Text style={styles.sosTitle}>SOS emergency help</Text><Text style={styles.sosSub}>Touch to call your saved contact</Text></View><Feather name="chevron-right" size={21} color="#fff" /></Pressable><View style={[styles.nextCard, { backgroundColor: colors.primary }]}><View style={styles.nextTop}><Text style={styles.onPrimaryEyebrow}>NEXT MEDICINE</Text><View style={styles.livePill}><View style={styles.liveDot} /><Text style={styles.liveText}>IN 42 MIN</Text></View></View><Text style={styles.nextTime}>{nextDose ? prettyTime(nextDose.time) : 'No more today'}</Text><Text style={styles.nextMedicine}>{nextDose?.name || 'All clear'} {nextDose?.strength || ''}</Text><Text style={styles.nextInstruction}>{nextDose ? `${nextDose.dose} tablet · With water` : 'You have completed your plan.'}</Text><Pressable onPress={onAlarm} style={styles.previewAlarm}><Feather name="bell" size={16} color="#fff" /><Text style={styles.previewAlarmText}>Preview alarm</Text></Pressable></View><Pressable onPress={onVoice} style={[styles.quickAction, { backgroundColor: colors.card, borderColor: colors.border }]}><Feather name="mic" size={22} color={colors.primary} /><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>Send a voice message</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Meena is listening</Text></View><Feather name="chevron-right" size={19} color={colors.mutedForeground} /></Pressable><View style={styles.sectionTitle}><Text style={[styles.h2, { color: colors.foreground }]}>Today’s medicine schedule</Text><Text style={[styles.link, { color: colors.primary }]}>Read-only</Text></View>{medicines.map((medicine: Medicine) => <PatientScheduleRow key={medicine.id} colors={colors} medicine={medicine} />)}</>;
}

function CaretakerHome({ colors, medicines, notices, onAdd, onPause, onDelete, onOpenAlarm }: any) { return <><View style={styles.greeting}><Text style={[styles.eyebrow, { color: colors.primary }]}>CARE CIRCLE · PRIMARY</Text><Text style={[styles.h1, { color: colors.foreground }]}>Good morning, Meena</Text><Text style={[styles.subhead, { color: colors.mutedForeground }]}>Monitoring Rajesh Kumar · MG-2048</Text></View><View style={styles.metricRow}><Metric colors={colors} value="3" label="Due today" icon="clock" /><Metric colors={colors} value="1" label="Waiting" icon="alert-circle" /></View><View style={styles.sectionTitle}><Text style={[styles.h2, { color: colors.foreground }]}>Today’s schedule</Text><Pressable onPress={onAdd}><Text style={[styles.link, { color: colors.primary }]}>+ Add</Text></Pressable></View>{medicines.map((m: Medicine) => <MedicineRow key={m.id} colors={colors} medicine={m} onPause={() => onPause(m)} onDelete={() => onDelete(m)} onOpenAlarm={onOpenAlarm} />)}<View style={styles.sectionTitle}><Text style={[styles.h2, { color: colors.foreground }]}>Recent activity</Text><Text style={[styles.link, { color: colors.primary }]}>{notices.filter((n: Notice) => !n.read).length} new</Text></View>{notices.slice(0, 2).map((n: Notice) => <View key={n.id} style={[styles.activity, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={[styles.activityIcon, { backgroundColor: n.kind === 'missed' ? '#fff0d5' : colors.secondary }]}><Feather name={n.kind === 'missed' ? 'alert-triangle' : 'bell'} size={16} color={n.kind === 'missed' ? '#c98227' : colors.primary} /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{n.title}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{n.body}</Text></View></View>)}</>; }
function DoctorHome({ colors, adherence, events, medicines }: any) { const taken = events.filter((e: Event) => e.status === 'taken').length; const missed = events.filter((e: Event) => e.status === 'missed').length; return <><View style={styles.greeting}><Text style={[styles.eyebrow, { color: colors.primary }]}>PATIENT OVERVIEW</Text><Text style={[styles.h1, { color: colors.foreground }]}>Rajesh Kumar</Text><Text style={[styles.subhead, { color: colors.mutedForeground }]}>MG-2048 · Updated just now</Text></View><View style={[styles.analyticsHero, { backgroundColor: colors.card, borderColor: colors.border }]}><CareCircle colors={colors} value={adherence} label="Adherence" /><View style={{ flex: 1, gap: 12 }}><MetricLine colors={colors} label="Taken" value={`${taken}`} color="#4aa884" /><MetricLine colors={colors} label="Waiting" value={`${events.filter((e: Event) => e.status === 'waiting').length}`} color="#c98227" /><MetricLine colors={colors} label="Missed" value={`${missed}`} color="#c83e58" /></View></View><View style={styles.sectionTitle}><Text style={[styles.h2, { color: colors.foreground }]}>Medication timeline</Text><Text style={[styles.link, { color: colors.primary }]}>7 days</Text></View><View style={[styles.chart, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={styles.chartBars}>{[48, 72, 60, 88, 76, 94, 82].map((h, i) => <View key={i} style={styles.barColumn}><View style={[styles.bar, { height: h * 0.8, backgroundColor: i === 5 ? colors.primary : '#efb4c9' }]} /><Text style={[styles.chartLabel, { color: colors.mutedForeground }]}>{['M', 'T', 'W', 'T', 'F', 'S', 'S'][i]}</Text></View>)}</View><Text style={[styles.caption, { color: colors.mutedForeground }]}>Tap a day in the full history to see every scheduled and actual response time.</Text></View>{medicines.map((m: Medicine) => <View key={m.id} style={[styles.medCard, { backgroundColor: colors.card, borderColor: colors.border }]}><Image source={m.photo === 'reference' ? referenceMedicine : { uri: m.photo }} style={styles.medImage} /><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{m.name}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{m.strength} · {m.frequency}</Text></View><Text style={[styles.percent, { color: colors.primary }]}>{adherence}%</Text></View>)}</>; }
function MedicineSection({ colors, role, medicines, onAdd, onPause, onDelete, onAlarm }: any) { return <><View style={styles.sectionHeader}><View><Text style={[styles.h1, { color: colors.foreground }]}>Medicines</Text><Text style={[styles.subhead, { color: colors.mutedForeground }]}>{medicines.length} active schedules · Rajesh Kumar</Text></View>{role === 'caretaker' && <Pressable onPress={onAdd} style={[styles.iconButton, { backgroundColor: colors.primary }]}><Feather name="plus" size={21} color="#fff" /></Pressable>}</View>{medicines.map((m: Medicine) => <MedicineRow key={m.id} colors={colors} medicine={m} onPause={() => onPause(m)} onDelete={role === 'caretaker' ? () => onDelete(m) : undefined} onOpenAlarm={onAlarm} />)}</>; }
function PeopleSection({ colors, role, connections, requests, onConnect, onRespond, onRemove }: any) {
  const visibleConnections: Connection[] = connections.length ? connections : role === 'patient' ? [{ id: 'primary', name: 'Meena Sharma', code: 'MG-C-1172', role: 'caretaker', relationship: 'Primary Caretaker', permission: 'Can manage medicines', initials: 'MS' }, { id: 'doctor', name: 'Dr. Vikram Shah', code: 'MG-D-7731', role: 'doctor', relationship: 'Connected Doctor', permission: 'Can view history', initials: 'VS' }] : [{ id: 'patient', name: 'Rajesh Kumar', code: 'MG-P-2048', role: 'patient', relationship: 'Father · Patient', permission: 'Full medication access', initials: 'RK' }];
  return <><View style={styles.sectionHeader}><View><Text style={[styles.h1, { color: colors.foreground }]}>{role === 'patient' ? 'My care circle' : 'My Patients'}</Text><Text style={[styles.subhead, { color: colors.mutedForeground }]}>Each connection shows its relationship and permission.</Text></View>{role === 'caretaker' && <Pressable onPress={onConnect} style={[styles.iconButton, { backgroundColor: colors.primary }]}><Feather name="user-plus" size={19} color="#fff" /></Pressable>}</View>{role === 'patient' && requests.filter((r: ConnectionRequest) => r.status === 'pending').map((r: ConnectionRequest) => <View key={r.id} style={[styles.requestCard, { backgroundColor: colors.secondary, borderColor: colors.primary }]}><View style={[styles.personAvatar, { backgroundColor: '#f4c3d3' }]}><Text style={styles.avatarText}>{r.requester.slice(0, 2).toUpperCase()}</Text></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{r.requester} wants to connect</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{r.code} · {r.relationship}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{r.permission}</Text><View style={styles.requestButtons}><Pressable onPress={() => onRespond(r, true)} style={[styles.smallButton, { backgroundColor: colors.primary }]}><Text style={styles.smallButtonText}>Confirm</Text></Pressable><Pressable onPress={() => onRespond(r, false)} style={[styles.smallButton, { backgroundColor: colors.card }]}><Text style={[styles.smallButtonText, { color: colors.foreground }]}>Decline</Text></Pressable></View></View></View>)}{visibleConnections.map((p) => <View key={p.id} style={[styles.personCard, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={[styles.personAvatar, { backgroundColor: '#f4c3d3' }]}><Text style={styles.avatarText}>{p.initials}</Text></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{p.name}</Text><Text style={[styles.caption, { color: colors.primary }]}>{p.relationship}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{p.code} · {p.permission}</Text></View>{p.relationship.includes('Daughter') && <Pressable onPress={onRemove}><Feather name="more-horizontal" size={22} color={colors.mutedForeground} /></Pressable>}</View>)}</>;
}
function HistorySection({ colors, events }: any) { return <><View style={styles.sectionHeader}><View><Text style={[styles.h1, { color: colors.foreground }]}>Medication history</Text><Text style={[styles.subhead, { color: colors.mutedForeground }]}>Scheduled time is separate from response time.</Text></View><Feather name="filter" size={20} color={colors.primary} /></View>{events.map((e: Event) => <View key={e.id} style={[styles.historyCard, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={[styles.statusIcon, { backgroundColor: e.status === 'taken' ? '#e4f5ef' : e.status === 'waiting' ? '#fff0d5' : '#ffe2e7' }]}><Feather name={e.status === 'taken' ? 'check' : e.status === 'waiting' ? 'clock' : 'x'} size={18} color={e.status === 'taken' ? '#398b72' : e.status === 'waiting' ? '#c98227' : '#c83e58'} /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{e.medicine}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Scheduled {new Date(e.scheduledAt).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}</Text>{e.respondedAt && <Text style={[styles.caption, { color: '#398b72' }]}>Responded {new Date(e.respondedAt).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}</Text>}<Text style={[styles.syncSmall, { color: colors.mutedForeground }]}>{e.sync} · {e.actor}</Text></View><Text style={[styles.statusText, { color: e.status === 'taken' ? '#398b72' : '#c98227' }]}>{e.status}</Text></View>)}</>; }
function ProfileSection({ colors, role, userCode, connections, sosNumber, onSOS, onLogout, onPeople }: any) { const profileName = role === 'doctor' ? 'Dr. Vikram Shah' : role === 'caretaker' ? 'Meena Sharma' : 'Rajesh Kumar'; return <><View style={styles.profileHero}><View style={[styles.profileAvatar, { backgroundColor: '#f4c3d3' }]}><Text style={styles.profileInitials}>{role === 'doctor' ? 'VS' : role === 'caretaker' ? 'MS' : 'RK'}</Text></View><Text style={[styles.h1, { color: colors.foreground }]}>{profileName}</Text><Text style={[styles.subhead, { color: colors.mutedForeground }]}>Connected as {role === 'patient' ? 'Patient' : role === 'caretaker' ? 'Primary Caretaker' : 'Doctor'}</Text><View style={[styles.codeCard, { backgroundColor: colors.secondary }]}><Text style={[styles.eyebrow, { color: colors.mutedForeground }]}>YOUR USERCODE</Text><Text style={[styles.userCode, { color: colors.primary }]}>{userCode}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Use this code when someone connects with you.</Text></View></View><Pressable onPress={onPeople} style={[styles.connectionSummary, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={styles.stackedAvatars}>{connections.slice(0, 3).map((c: Connection, i: number) => <View key={c.id} style={[styles.tinyAvatar, { backgroundColor: i === 0 ? '#f4c3d3' : '#f8dfb4', marginLeft: i ? -8 : 0 }]}><Text style={styles.tinyAvatarText}>{c.initials}</Text></View>)}</View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{connections.length || 2} connections</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>View your care circle</Text></View><Feather name="chevron-right" size={19} color={colors.mutedForeground} /></Pressable>{role === 'patient' && <Pressable onPress={onSOS} style={styles.sos}><Feather name="phone-call" size={21} color="#fff" /><View style={{ flex: 1 }}><Text style={styles.sosTitle}>SOS help</Text><Text style={styles.sosSub}>{sosNumber || 'Add an emergency number'}</Text></View></Pressable>}{['Personal details', 'Notifications', 'Security', 'Appearance', 'Medi_Loaded device'].map((x) => <Pressable key={x} onPress={() => Alert.alert(x, `${x} settings are saved to this profile.`)} style={[styles.settingsRow, { borderBottomColor: colors.border }]}><Feather name={x === 'Notifications' ? 'bell' : x === 'Security' ? 'lock' : x === 'Appearance' ? 'sun' : 'user'} size={20} color={colors.primary} /><Text style={[styles.rowTitle, { color: colors.foreground, flex: 1 }]}>{x}</Text><Feather name="chevron-right" size={18} color={colors.mutedForeground} /></Pressable>)}<Pressable onPress={onLogout} style={[styles.logoutRow, { borderColor: colors.border }]}><Feather name="log-out" size={18} color={colors.destructive} /><Text style={[styles.rowTitle, { color: colors.destructive }]}>Sign out</Text></Pressable></>; }
function Alarm({ colors, medicine, onTick, onSnooze, onVoice, onClose }: any) { return <View style={[styles.alarm, { backgroundColor: colors.background }]}><View style={styles.alarmTop}><Pressable onPress={onClose} style={styles.closeCircle}><Feather name="x" size={22} color={colors.foreground} /></Pressable><Text style={[styles.eyebrow, { color: colors.primary }]}>MEDIGUARD REMINDER</Text><View style={{ width: 40 }} /></View><View style={[styles.messageBubble, { backgroundColor: colors.card }]}><View style={[styles.smallAvatar, { backgroundColor: '#f4c3d3' }]}><Text style={styles.avatarText}>MS</Text></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>Meena Sharma</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>“You’ve got this, Papa.”</Text></View><Feather name="volume-2" size={20} color={colors.primary} /></View><Image source={medicine?.photo === 'reference' ? referenceMedicine : { uri: medicine?.photo }} style={styles.alarmMedicine} /><Text style={[styles.alarmName, { color: colors.foreground }]}>{medicine?.name || 'Medicine'}</Text><Text style={[styles.alarmInfo, { color: colors.primary }]}>{medicine?.strength || '5 mg'} · {medicine?.dose || 1} tablet</Text><Text style={[styles.alarmBilingual, { color: colors.mutedForeground }]}>Take with water · पानी के साथ लें</Text><View style={styles.alarmActions}><Pressable testID="alarm-tick" onPress={() => medicine && onTick(medicine)} style={[styles.tickButton, { backgroundColor: '#4aa884' }]}><Feather name="check" size={42} color="#fff" /><Text style={styles.alarmActionText}>TICK</Text></Pressable><Pressable testID="alarm-mic" onPress={onVoice} style={[styles.tickButton, { backgroundColor: colors.primary }]}><Feather name="mic" size={38} color="#fff" /><Text style={styles.alarmActionText}>SPEAK</Text></Pressable></View><Pressable testID="alarm-snooze" onPress={onSnooze} style={[styles.snoozeButton, { backgroundColor: colors.secondary, borderColor: colors.border }]}><Feather name="clock" size={16} color={colors.primary} /><Text style={[styles.snooze, { color: colors.primary }]}>Remind me in 5 minutes</Text></Pressable></View>; }
function CareCircle({ colors, value, label }: any) { return <View style={styles.circleWrap}><View style={[styles.circle, { borderColor: colors.secondary }]}><View style={[styles.circleInner, { backgroundColor: colors.card }]}><Text style={[styles.circleValue, { color: colors.primary }]}>{value}%</Text></View></View><Text style={[styles.circleLabel, { color: colors.mutedForeground }]}>{label}</Text></View>; }
function MiniRow({ colors, icon, title, detail, done }: any) { return <View style={styles.miniRow}><Feather name={icon} size={18} color={done ? '#4aa884' : '#c98227'} /><View><Text style={[styles.rowTitle, { color: colors.foreground }]}>{title}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{detail}</Text></View></View>; }
function Metric({ colors, value, label, icon }: any) { return <View style={[styles.metric, { backgroundColor: colors.card, borderColor: colors.border }]}><Feather name={icon} size={18} color={colors.primary} /><Text style={[styles.metricValue, { color: colors.foreground }]}>{value}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{label}</Text></View>; }
function MetricLine({ colors, label, value, color }: any) { return <View style={styles.metricLine}><View style={[styles.metricDot, { backgroundColor: color }]} /><Text style={[styles.caption, { color: colors.mutedForeground, flex: 1 }]}>{label}</Text><Text style={[styles.rowTitle, { color: colors.foreground }]}>{value}</Text></View>; }
function PatientScheduleRow({ colors, medicine }: any) { return <View style={[styles.scheduleRow, { backgroundColor: colors.card, borderColor: colors.border }]}><View style={[styles.scheduleIcon, { backgroundColor: colors.secondary }]}><Feather name="clock" size={17} color={colors.primary} /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{medicine.name}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{medicine.strength} · {medicine.dose} tablet · {medicine.frequency}</Text></View><View style={styles.scheduleTimes}>{medicine.times.map((time: string) => <Text key={time} style={[styles.timeChip, { backgroundColor: colors.secondary, color: colors.primary }]}>{prettyTime(time)}</Text>)}</View></View>; }
function MedicineRow({ colors, medicine, onPause, onDelete, onOpenAlarm }: any) { return <View style={[styles.medRow, { backgroundColor: colors.card, borderColor: colors.border }]}><Image source={medicine.photo === 'reference' ? referenceMedicine : { uri: medicine.photo }} style={styles.medThumb} /><View style={{ flex: 1 }}><View style={styles.rowTop}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{medicine.name}</Text><View style={[styles.statePill, { backgroundColor: medicine.state === 'paused' ? '#fff0d5' : '#e4f5ef' }]}><Text style={[styles.stateText, { color: medicine.state === 'paused' ? '#c98227' : '#398b72' }]}>{medicine.state}</Text></View></View><Text style={[styles.caption, { color: colors.mutedForeground }]}>{medicine.strength} · {medicine.dose} tablet · {medicine.frequency}</Text><View style={styles.timeChips}>{medicine.times.map((t: string) => <Text key={t} style={[styles.timeChip, { backgroundColor: colors.secondary, color: colors.primary }]}>{prettyTime(t)}</Text>)}</View><Text style={[styles.syncSmall, { color: colors.mutedForeground }]}>Changed by {medicine.changedBy} · through Oct 31</Text></View><View style={styles.medActions}><Pressable onPress={onOpenAlarm}><Feather name="eye" size={18} color={colors.primary} /></Pressable><Pressable onPress={onPause}><Feather name={medicine.state === 'paused' ? 'play' : 'pause'} size={18} color={colors.mutedForeground} /></Pressable>{onDelete && <Pressable testID={`delete-${medicine.id}`} onPress={onDelete}><Feather name="trash-2" size={18} color={colors.destructive} /></Pressable>}</View></View>; }
function InventorySection({ colors, inventory, onAdjust }: any) { return <><View style={styles.sectionHeader}><View><Text style={[styles.h1, { color: colors.foreground }]}>Medicine stock</Text><Text style={[styles.subhead, { color: colors.mutedForeground }]}>Track Rajesh’s remaining medicine and refill early.</Text></View><Feather name="archive" size={22} color={colors.primary} /></View><View style={[styles.inventoryNote, { backgroundColor: colors.secondary }]}><Feather name="info" size={17} color={colors.primary} /><Text style={[styles.caption, { color: colors.foreground, flex: 1 }]}>Stock decreases automatically when the Patient ticks a dose.</Text></View>{inventory.map((item: InventoryItem) => { const low = item.count <= item.threshold; return <View key={item.medicineId} style={[styles.inventoryCard, { backgroundColor: colors.card, borderColor: low ? '#e4a04b' : colors.border }]}><View style={styles.inventoryTop}><View style={[styles.inventoryIcon, { backgroundColor: low ? '#fff0d5' : colors.secondary }]}><Feather name={low ? 'alert-triangle' : 'package'} size={19} color={low ? '#c98227' : colors.primary} /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{item.name}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>Refill threshold: {item.threshold} {item.unit}</Text></View><View style={styles.inventoryCount}><Text style={[styles.inventoryNumber, { color: low ? '#c98227' : colors.primary }]}>{item.count}</Text><Text style={[styles.caption, { color: colors.mutedForeground }]}>{item.unit}</Text></View></View><View style={[styles.stockBar, { backgroundColor: colors.muted }]}><View style={[styles.stockFill, { width: `${Math.min(100, (item.count / Math.max(item.threshold * 3, 1)) * 100)}%`, backgroundColor: low ? '#e4a04b' : colors.primary }]} /></View>{low && <Text style={[styles.lowStockText, { color: '#c98227' }]}>Low stock — refill {item.name} soon.</Text>}<View style={styles.inventoryActions}><Text style={[styles.caption, { color: colors.mutedForeground }]}>Caretaker adjustment</Text><View style={styles.adjustButtons}><Pressable testID={`decrease-${item.medicineId}`} onPress={() => onAdjust(item.medicineId, -1)} style={[styles.adjustButton, { borderColor: colors.border }]}><Feather name="minus" size={16} color={colors.primary} /></Pressable><Pressable testID={`increase-${item.medicineId}`} onPress={() => onAdjust(item.medicineId, 1)} style={[styles.adjustButton, { backgroundColor: colors.primary }]}><Feather name="plus" size={16} color="#fff" /></Pressable></View></View></View>; })}</>; }

